CREATE TABLE IF NOT EXISTS users (id VARCHAR(36) PRIMARY KEY, username VARCHAR(100) UNIQUE NOT NULL, name VARCHAR(150) NOT NULL, password_hash VARCHAR(255) NOT NULL, role ENUM('ADMIN','COORDINATOR','STUDENT') NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, enrolment VARCHAR(80) UNIQUE, programme VARCHAR(120), semester INT);
CREATE TABLE IF NOT EXISTS sessions (token_hash CHAR(64) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, expires_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS locations (id VARCHAR(36) PRIMARY KEY, name VARCHAR(150) NOT NULL, parent_id VARCHAR(36), FOREIGN KEY(parent_id) REFERENCES locations(id));
CREATE TABLE IF NOT EXISTS categories (id VARCHAR(36) PRIMARY KEY, name VARCHAR(100) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS items (id VARCHAR(36) PRIMARY KEY, code VARCHAR(80) UNIQUE NOT NULL, name VARCHAR(150) NOT NULL, category_id VARCHAR(36) NOT NULL, description TEXT NOT NULL, model VARCHAR(150) NOT NULL, unit VARCHAR(30) NOT NULL, tracking ENUM('BULK','INDIVIDUAL') NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY(category_id) REFERENCES categories(id));
CREATE TABLE IF NOT EXISTS balances (item_id VARCHAR(36) NOT NULL, location_id VARCHAR(36) NOT NULL, bucket ENUM('USABLE','DAMAGED','MAINTENANCE','LOST','RETIRED') NOT NULL, quantity INT NOT NULL DEFAULT 0 CHECK(quantity>=0), PRIMARY KEY(item_id,location_id,bucket), FOREIGN KEY(item_id) REFERENCES items(id), FOREIGN KEY(location_id) REFERENCES locations(id));
CREATE TABLE IF NOT EXISTS assets (id VARCHAR(36) PRIMARY KEY, item_id VARCHAR(36) NOT NULL, location_id VARCHAR(36) NOT NULL, tag VARCHAR(100) UNIQUE NOT NULL, serial VARCHAR(100) NOT NULL, status ENUM('USABLE','ISSUED','DAMAGED','MAINTENANCE','LOST','RETIRED') NOT NULL, FOREIGN KEY(item_id) REFERENCES items(id), FOREIGN KEY(location_id) REFERENCES locations(id));
CREATE TABLE IF NOT EXISTS issues (id VARCHAR(36) PRIMARY KEY, student_id VARCHAR(36) NOT NULL, item_id VARCHAR(36) NOT NULL, asset_id VARCHAR(36), location_id VARCHAR(36) NOT NULL, quantity INT NOT NULL CHECK(quantity>0), returned INT NOT NULL DEFAULT 0 CHECK(returned>=0), issued_on DATE NOT NULL, due_on DATE NOT NULL, purpose TEXT NOT NULL, actor_id VARCHAR(36) NOT NULL, renewals INT NOT NULL DEFAULT 0, FOREIGN KEY(student_id) REFERENCES users(id), FOREIGN KEY(item_id) REFERENCES items(id), FOREIGN KEY(asset_id) REFERENCES assets(id), FOREIGN KEY(location_id) REFERENCES locations(id), FOREIGN KEY(actor_id) REFERENCES users(id), INDEX(due_on), CHECK(returned<=quantity));
CREATE TABLE IF NOT EXISTS returns (id VARCHAR(36) PRIMARY KEY, issue_id VARCHAR(36) NOT NULL, quantity INT NOT NULL CHECK(quantity>0), condition_code VARCHAR(30) NOT NULL, remarks TEXT NOT NULL, actor_id VARCHAR(36) NOT NULL, created_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(issue_id) REFERENCES issues(id), FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS renewals (id VARCHAR(36) PRIMARY KEY, issue_id VARCHAR(36) NOT NULL, reason TEXT NOT NULL, status ENUM('PENDING','APPROVED','REJECTED') NOT NULL DEFAULT 'PENDING', old_due DATE NOT NULL, new_due DATE, remarks TEXT, actor_id VARCHAR(36), created_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(issue_id) REFERENCES issues(id), FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS movements (id VARCHAR(36) PRIMARY KEY, item_id VARCHAR(36) NOT NULL, location_id VARCHAR(36) NOT NULL, bucket VARCHAR(30) NOT NULL, delta INT NOT NULL, reason TEXT NOT NULL, actor_id VARCHAR(36) NOT NULL, created_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(item_id) REFERENCES items(id), FOREIGN KEY(location_id) REFERENCES locations(id), FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS audit (id VARCHAR(36) PRIMARY KEY, actor_id VARCHAR(36) NOT NULL, action VARCHAR(80) NOT NULL, entity_id VARCHAR(36) NOT NULL, details JSON NOT NULL, created_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS idempotency (actor_id VARCHAR(36) NOT NULL, operation VARCHAR(180) NOT NULL, request_key VARCHAR(100) NOT NULL, request_hash CHAR(64) NOT NULL, response JSON, PRIMARY KEY(actor_id,operation,request_key), FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS policies (id INT PRIMARY KEY, max_units INT NOT NULL, max_renewals INT NOT NULL, allow_overdue BOOLEAN NOT NULL);
